      var sessionAdmin = false;
      try { sessionAdmin = sessionStorage.getItem('fdsSessionAdmin') === 'ok'; } catch (e) {}
      // ---------- Navigation par pages ----------
      var routes = ['accueil', 'parti', 'poles', 'bureaux', 'bureau', 'diaspora', 'publications', 'activites', 'adhesion', 'auth', 'espace', 'espace-badge', 'espace-infos', 'espace-actus', 'espace-offres', 'admin', 'admin-membres', 'admin-actus', 'admin-offres', 'admin-orga', 'carte', 'mentions'];
      var pagesSite = ['accueil', 'parti', 'poles', 'bureaux', 'bureau', 'diaspora', 'publications', 'activites', 'adhesion', 'auth', 'espace', 'admin', 'carte', 'mentions'];
      function pageId(route) {
        if (route.indexOf('admin') === 0) return 'admin';
        if (route.indexOf('espace') === 0) return 'espace';
        return route;
      }
      var titresPages = {
        accueil: 'FDS — Front Démocratique Socialiste | Pour un Gabon juste, libre et prospère',
        parti: 'Le Parti — FDS',
        poles: 'Nos pôles d\u2019action — FDS',
        bureaux: 'Nos bureaux — FDS',
        bureau: 'Bureau — FDS',
        diaspora: 'Diaspora — FDS',
        publications: 'Publications — FDS',
        activites: 'Activités — FDS',
        adhesion: 'Adhérer — FDS',
        auth: 'Espace membre — FDS',
        espace: 'Mon espace membre — FDS',
        admin: 'Tableau de bord admin — FDS',
        mentions: 'Mentions légales — FDS',
        carte: 'Carte de membre — FDS'
      };
      var ancreEnAttente = null;

      function routeDepuisHash() {
        var h = (location.hash || '').replace(/^#/, '');
        var route = h.split('/')[0];
        try { route = decodeURIComponent(route); } catch (e) {}
        return routes.indexOf(route) !== -1 ? route : 'accueil';
      }

      function afficherPage(route) {
        var id = pageId(route);
        pagesSite.forEach(function (r) {
          var el = document.getElementById('page-' + r);
          if (el) el.classList.toggle('actif', r === id);
        });
        document.title = titresPages[id] || titresPages.accueil;
        document.body.classList.toggle('mode-tableau', id === 'espace' || id === 'admin');
        majBarreTableau(route);
        if (id === 'espace') majEspace();
        if (id === 'admin') majAdmin();
        if (id === 'carte') rendreCarte();
        if (route === 'bureau') { rendreBureau(bureauEnAttente || bureauCourant); bureauEnAttente = null; }
        document.querySelectorAll('nav.liens a[data-route]').forEach(function (a) {
          a.classList.toggle('actif', a.getAttribute('data-route') === route);
        });
        var cible = ancreEnAttente ? document.getElementById(ancreEnAttente) : null;
        ancreEnAttente = null;
        if (cible) {
          setTimeout(function () { cible.scrollIntoView({ behavior: 'smooth', block: 'start' }); }, 60);
        } else {
          window.scrollTo(0, 0);
        }
      }

      function majBarreTableau(route) {
        var titre = document.getElementById('titreTableau');
        if (!titre) return;
        var libelles = {
          admin: 'Tableau de bord admin',
          'admin-membres': 'Membres',
          'admin-actus': 'Actualités',
          'admin-offres': 'Offres',
          'admin-orga': 'Organigrammes',
          espace: 'Espace membre',
          'espace-badge': 'Mon badge',
          'espace-infos': 'Mes informations',
          'espace-actus': 'Actualités',
          'espace-offres': 'Offres'
        };
        if (libelles[route]) titre.textContent = libelles[route];
        var id = pageId(route);
        var connecte = (id === 'admin' && sessionAdmin) || (id === 'espace' && !!sessionMembre);
        var quitter = document.getElementById('btnQuitterTableau');
        if (quitter) quitter.hidden = !connecte;
      }
      // Clics sur les liens internes : mémorise l'ancre éventuelle, laisse le hash piloter l'affichage
      document.querySelectorAll('a[href^="#"]').forEach(function (a) {
        a.addEventListener('click', function (e) {
          var route = a.getAttribute('href').slice(1);
          if (routes.indexOf(route) === -1) return;
          ancreEnAttente = a.getAttribute('data-ancre');
          var bureauLien = a.getAttribute('data-bureau');
          if (bureauLien) bureauEnAttente = bureauLien;
          if (routeDepuisHash() === route) {
            e.preventDefault();
            afficherPage(route);
          }
        });
      });
      window.addEventListener('hashchange', function () { afficherPage(routeDepuisHash()); });

      // Menu mobile
      var burger = document.getElementById('burger');
      var menu = document.getElementById('menuMobile');
      function fermerGroupes() {
        menu.querySelectorAll('.groupe.ouvert').forEach(function (g) {
          g.classList.remove('ouvert');
          g.querySelector('.groupe-titre').setAttribute('aria-expanded', 'false');
        });
      }
      function fermerMenu() {
        menu.classList.remove('ouvert');
        burger.setAttribute('aria-expanded', 'false');
        burger.setAttribute('aria-label', 'Ouvrir le menu');
        fermerGroupes();
      }
      burger.addEventListener('click', function () {
        var ouvert = menu.classList.toggle('ouvert');
        burger.setAttribute('aria-expanded', ouvert ? 'true' : 'false');
        burger.setAttribute('aria-label', ouvert ? 'Fermer le menu' : 'Ouvrir le menu');
        if (!ouvert) fermerGroupes();
      });
      menu.querySelectorAll('.groupe-titre').forEach(function (btn) {
        btn.addEventListener('click', function (e) {
          e.stopPropagation();
          var groupe = btn.parentElement;
          var ouvert = groupe.classList.toggle('ouvert');
          btn.setAttribute('aria-expanded', ouvert ? 'true' : 'false');
        });
      });
      menu.addEventListener('click', function (e) {
        if (e.target.closest && e.target.closest('a')) fermerMenu();
      });

      // Menus déroulants de la navigation (clic, pour le tactile)
      var deroulants = document.querySelectorAll('.deroulant');
      function fermerDeroulants() {
        deroulants.forEach(function (d) {
          d.classList.remove('ouvert');
          d.querySelector('.declencheur').setAttribute('aria-expanded', 'false');
        });
      }
      deroulants.forEach(function (d) {
        var btn = d.querySelector('.declencheur');
        btn.addEventListener('click', function (e) {
          e.stopPropagation();
          var dejaOuvert = d.classList.contains('ouvert');
          fermerDeroulants();
          if (!dejaOuvert) {
            d.classList.add('ouvert');
            btn.setAttribute('aria-expanded', 'true');
          }
        });
        d.querySelectorAll('.panneau a').forEach(function (a) {
          a.addEventListener('click', fermerDeroulants);
        });
      });
      document.addEventListener('click', fermerDeroulants);
      document.addEventListener('keydown', function (e) {
        if (e.key === 'Escape') fermerDeroulants();
      });

      // Authentification : bascule Connexion / Création de compte
      var ongletConnexion = document.getElementById('ongletConnexion');
      var ongletInscription = document.getElementById('ongletInscription');
      var panneauConnexion = document.getElementById('panneauConnexion');
      var panneauInscription = document.getElementById('panneauInscription');
      function afficherAuth(vue) {
        var insc = vue === 'inscription';
        panneauInscription.classList.toggle('actif', insc);
        panneauConnexion.classList.toggle('actif', !insc);
        ongletInscription.classList.toggle('actif', insc);
        ongletConnexion.classList.toggle('actif', !insc);
        ongletInscription.setAttribute('aria-selected', insc ? 'true' : 'false');
        ongletConnexion.setAttribute('aria-selected', insc ? 'false' : 'true');
      }
      ongletConnexion.addEventListener('click', function () { afficherAuth('connexion'); });
      ongletInscription.addEventListener('click', function () { afficherAuth('inscription'); });
      document.querySelectorAll('[data-vue]').forEach(function (el) {
        el.addEventListener('click', function () { afficherAuth(el.getAttribute('data-vue')); });
      });
      document.querySelectorAll('[data-vue-lien]').forEach(function (el) {
        el.addEventListener('click', function () { afficherAuth(el.getAttribute('data-vue-lien')); });
      });

      // Création de compte : aperçu de la photo choisie
      var inputPhoto = document.getElementById('insPhoto');
      var apercuPhoto = document.getElementById('apercuPhoto');
      var nomPhoto = '';
      inputPhoto.addEventListener('change', function () {
        var fichier = inputPhoto.files && inputPhoto.files[0];
        nomPhoto = fichier ? fichier.name : '';
        if (fichier && window.FileReader) {
          var lecteur = new FileReader();
          lecteur.onload = function (ev) {
            apercuPhoto.src = ev.target.result;
            apercuPhoto.classList.add('visible');
          };
          lecteur.readAsDataURL(fichier);
        } else {
          apercuPhoto.classList.remove('visible');
          apercuPhoto.removeAttribute('src');
        }
      });

      // Création de compte : prépare le récapitulatif que le visiteur peut copier et transmettre
      var formInscription = document.getElementById('formInscription');
      var resultatInscription = document.getElementById('resultatInscription');
      var texteInscription = document.getElementById('texteInscription');
      var copieOkInscription = document.getElementById('copieOkInscription');
      var erreurInscription = document.getElementById('erreurInscription');
      function valeur(id) { return document.getElementById(id).value.trim(); }
      function dateFr(iso) {
        var p = iso.split('-');
        return p.length === 3 ? p[2] + '/' + p[1] + '/' + p[0] : iso;
      }
      formInscription.addEventListener('submit', function (e) {
        e.preventDefault();
        var nom = valeur('insNom');
        var prenom = valeur('insPrenom');
        var tel = valeur('insTel');
        var email = valeur('insEmail');
        if (!nom || !prenom || !tel || !email) {
          erreurInscription.hidden = false;
          resultatInscription.classList.remove('visible');
          erreurInscription.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
          return;
        }
        erreurInscription.hidden = true;
        var lignes = [
          'INSCRIPTION \u2014 FRONT D\u00c9MOCRATIQUE SOCIALISTE (FDS)',
          'Nom : ' + nom,
          'Pr\u00e9nom : ' + prenom
        ];
        var genre = valeur('insGenre');
        if (genre) lignes.push('Genre : ' + genre);
        var naissance = valeur('insNaissance');
        if (naissance) lignes.push('Date de naissance : ' + dateFr(naissance));
        var lieuNaissance = valeur('insLieuNaissance');
        if (lieuNaissance) lignes.push('Lieu de naissance : ' + lieuNaissance);
        var profession = valeur('insProfession');
        if (profession) lignes.push('Profession : ' + profession);
        var ville = valeur('insVille');
        if (ville) lignes.push('Ville de r\u00e9sidence : ' + ville);
        var region = valeur('insRegion');
        if (region) lignes.push('R\u00e9gion : ' + region);
        var pays = valeur('insPays');
        if (pays) lignes.push('Pays : ' + pays);
        lignes.push('T\u00e9l\u00e9phone : ' + tel);
        lignes.push('E-mail : ' + email);
        var nip = valeur('insNip');
        if (nip) lignes.push('Num\u00e9ro d\u2019identification personnelle (NIP) : ' + nip);
        var circonscription = valeur('insCirconscription');
        if (circonscription) lignes.push('Circonscription \u00e9lectorale : ' + circonscription);
        var lieuVote = valeur('insLieuVote');
        if (lieuVote) lignes.push('Lieu de vote : ' + lieuVote);
        lignes.push(nomPhoto ? 'Photo : jointe (' + nomPhoto + ')' : 'Photo : non fournie');
        lignes.push('Cotisation : 500 FCFA, en attente d\u2019activation par le bureau');
        lignes.push('Devise : Respect \u2014 Int\u00e9grit\u00e9 \u2014 Loyaut\u00e9');
        // Enregistre le membre (visible dans son espace et dans le tableau de bord admin)
        dernierProfil = {
          nom: nom, prenom: prenom, genre: genre, naissance: naissance,
          lieuNaissance: lieuNaissance, profession: profession, ville: ville,
          region: region, pays: pays, tel: tel, email: email, nip: nip,
          circonscription: circonscription, lieuVote: lieuVote,
          photo: apercuPhoto.classList.contains('visible') ? apercuPhoto.src : '',
          numero: nouveauNumero(), cotisation: null, actif: false
        };
        membresInscrits.push(dernierProfil);
        texteInscription.textContent = lignes.join('\n');
        copieOkInscription.hidden = true;
        resultatInscription.classList.add('visible');
        resultatInscription.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      });
      document.getElementById('btnCopieInscription').addEventListener('click', function () {
        var texte = texteInscription.textContent;
        function ok() { copieOkInscription.hidden = false; }
        if (navigator.clipboard && navigator.clipboard.writeText) {
          navigator.clipboard.writeText(texte).then(ok, function () { repli(); });
        } else { repli(); }
        function repli() {
          var ta = document.createElement('textarea');
          ta.value = texte;
          document.body.appendChild(ta);
          ta.select();
          try { document.execCommand('copy'); ok(); } catch (err) {}
          document.body.removeChild(ta);
        }
      });

      // Connexion : ouvre l'espace membre avec le badge numérique du membre
      var note = document.getElementById('noteConnexion');
      var erreurConnexion = document.getElementById('erreurConnexion');
      document.getElementById('formConnexion').addEventListener('submit', function (e) {
        e.preventDefault();
        var identifiant = valeur('email');
        var mdp = valeur('mdp');
        if (!identifiant || !mdp) {
          erreurConnexion.hidden = false;
          return;
        }
        erreurConnexion.hidden = true;
        note.classList.remove('visible');
        sessionMembre = profilPourIdentifiant(identifiant);
        allerEspace();
      });
      document.getElementById('lienOublie').addEventListener('click', function (e) {
        e.preventDefault();
        afficherPage('auth');
        note.classList.add('visible');
      });
      document.getElementById('btnEspaceInscription').addEventListener('click', function () {
        if (dernierProfil) {
          sessionMembre = dernierProfil;
          allerEspace();
        }
      });
      document.getElementById('btnDeconnexion').addEventListener('click', function () {
        sessionMembre = null;
        location.hash = '#accueil';
      });

      // ---------- État de la session et contenus gérés ----------
      var sessionMembre = null;
      var membresInscrits = [];
      var dernierProfil = null;
      var compteurNumero = 0;
      var actualites = [
        { titre: 'Campagne d\u2019adhésion ouverte', texte: 'Les inscriptions sont ouvertes dans tous les bureaux du FDS, au Gabon comme dans la diaspora. Invite tes proches à créer leur compte et à rejoindre le bureau le plus proche de chez eux.' },
        { titre: 'Les six pôles d\u2019action recrutent', texte: 'Diaspora et retour, Économie, Social, Communication, Citoyenneté, Institutions : choisis le chantier qui te parle et engage-toi avec ton pôle.' }
      ];
      var offres = [
        { titre: 'Accès prioritaire aux activités du parti', texte: 'Les membres inscrits sont prioritaires pour les rencontres, forums et actions de terrain organisés par leur bureau.' },
        { titre: 'Publications réservées aux membres', texte: 'Communiqués et documents du parti en avant-première, directement dans ton espace membre.' }
      ];

      function echapper(s) {
        return String(s == null ? '' : s)
          .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
          .replace(/"/g, '&quot;');
      }
      function nouveauNumero() {
        compteurNumero += 1;
        var n = '000' + compteurNumero;
        return 'FDS-' + new Date().getFullYear() + '-' + n.slice(-4);
      }
      function bureauDe(p) {
        var pays = (p.pays || 'Gabon').toLowerCase();
        if (pays.indexOf('france') !== -1) return 'FDS France';
        if (pays.indexOf('sénégal') !== -1 || pays.indexOf('senegal') !== -1) return 'FDS Sénégal';
        if (pays && pays !== 'gabon') return 'FDS Diaspora';
        var region = p.region || p.province || '';
        return region ? 'Bureau — ' + region : 'Bureau national';
      }
      function initiales(p) {
        var a = (p.prenom || '').charAt(0);
        var b = (p.nom || '').charAt(0);
        return (a + b).toUpperCase() || 'FDS';
      }
      function profilPourIdentifiant(identifiant) {
        var id = identifiant.toLowerCase();
        for (var i = 0; i < membresInscrits.length; i++) {
          var m = membresInscrits[i];
          if (m.email.toLowerCase() === id || m.tel.replace(/\s/g, '') === id.replace(/\s/g, '')) return m;
        }
        var base = identifiant.indexOf('@') !== -1 ? identifiant.split('@')[0] : identifiant;
        var morceaux = base.split(/[._-]+/).filter(function (x) { return x; });
        function cap(x) { return x ? x.charAt(0).toUpperCase() + x.slice(1) : ''; }
        var somme = 0;
        for (var j = 0; j < identifiant.length; j++) somme += identifiant.charCodeAt(j);
        var num = '000' + (somme % 9000 + 1000);
        return {
          nom: cap(morceaux[1] || morceaux[0] || 'Membre'), prenom: cap(morceaux[0] || 'Membre'),
          genre: '', naissance: '', lieuNaissance: '', profession: '', ville: '', region: '',
          pays: 'Gabon', tel: identifiant.indexOf('@') !== -1 ? '' : identifiant,
          email: identifiant.indexOf('@') !== -1 ? identifiant : '', nip: '',
          circonscription: '', lieuVote: '', photo: '',
          numero: 'FDS-' + new Date().getFullYear() + '-' + num.slice(-4),
          cotisation: null, actif: false
        };
      }
      function allerEspace() {
        if (routeDepuisHash() === 'espace') { afficherPage('espace'); }
        else { location.hash = '#espace'; }
      }

      // ---------- Rendu de l'espace membre ----------
      function majEspace() {
        var invite = document.getElementById('espaceInvite');
        var contenu = document.getElementById('espaceContenu');
        if (!sessionMembre) {
          invite.hidden = false;
          contenu.hidden = true;
          return;
        }
        invite.hidden = true;
        contenu.hidden = false;
        var p = sessionMembre;
        document.getElementById('bonjourNom').textContent = 'Bonjour, ' + p.prenom + ' ' + p.nom;
        rendreBadge(p);
        rendreInfos(p);
        rendreCotisation(p);
        rendreFlux();
        majSectionEspace(routeDepuisHash());
      }
      function indexHash() {
        var h = (location.hash || '').replace(/^#/, '');
        var i = h.indexOf('/');
        if (i < 0) return -1;
        var n = parseInt(h.slice(i + 1), 10);
        return isNaN(n) || n < 0 ? -1 : n;
      }
      function majSectionEspace(route) {
        var section = route.indexOf('espace-') === 0 ? route.slice(7) : 'hub';
        if (section === 'badge') section = 'hub';
        var index = indexHash();
        var detail = (section === 'actus' || section === 'offres') && index >= 0;
        var vues = { infos: 'espaceVueInfos', actus: 'espaceVueActus', offres: 'espaceVueOffres' };
        var hub = document.getElementById('espaceHub');
        if (hub) hub.hidden = section !== 'hub';
        Object.keys(vues).forEach(function (cle) {
          var el = document.getElementById(vues[cle]);
          if (el) el.hidden = detail || section !== cle;
        });
        var fiche = document.getElementById('espaceVueDetail');
        if (fiche) fiche.hidden = !detail;
        if (detail) rendreFiche(section, index);
        var retour = document.getElementById('retourEspace');
        if (retour) retour.hidden = section === 'hub';
      }
      function lienCarte(p) {
        var data = [p.numero || '', p.prenom || '', p.nom || '', p.ville || '', p.pays || '', p.profession || ''].join('|');
        var base = location.href.split('#')[0].split('?')[0];
        return base + '#carte/' + encodeURIComponent(data);
      }
      function qrSrc(p) {
        try {
          var qr = qrcode(0, 'M');
          qr.addData(lienCarte(p));
          qr.make();
          return qr.createDataURL(6, 2);
        } catch (errQr) {
          return '';
        }
      }
      function lireCarte() {
        var h = (location.hash || '').replace(/^#/, '');
        var i = h.indexOf('/');
        if (i < 0) return null;
        try { h = decodeURIComponent(h.slice(i + 1)); } catch (e) { h = h.slice(i + 1); }
        var m = h.split('|');
        if (!m[0] || !m[1] || !m[2]) return null;
        return { numero: m[0], prenom: m[1], nom: m[2], ville: m[3] || '', pays: m[4] || '', profession: m[5] || '', region: '' };
      }
      function rendreCarte() {
        var cible = document.getElementById('carteScan');
        var note = document.getElementById('carteNote');
        if (!cible) return;
        var p = lireCarte();
        if (!p) {
          cible.innerHTML = '';
          if (note) note.textContent = 'Ce QR code ne correspond pas à un badge FDS.';
          return;
        }
        cible.innerHTML = htmlBadge(p);
        if (note) note.textContent = 'Badge vérifié : ' + p.prenom + ' ' + p.nom + ' — ' + p.numero;
      }
      function htmlBadge(p) {
        var photo = p.photo
          ? '<img class="badge-photo" src="' + p.photo + '" alt="Photo de ' + echapper(p.prenom + ' ' + p.nom) + '" />'
          : '<div class="badge-initiales" aria-hidden="true">' + echapper(initiales(p)) + '</div>';
        return (
          '<div class="badge-dedans">' +
            '<div class="badge-haut">' +
              '<span class="logo"><img src="data:image/png;base64," alt="" /></span>' +
              '<span class="parti"><strong>FDS</strong><small>Front Démocratique Socialiste</small></span>' +
            '</div>' +
            '<p class="badge-titre">Carte de membre</p>' +
            '<div class="badge-corps">' + photo +
              '<div><div class="badge-nom">' + echapper(p.prenom) + ' ' + echapper(p.nom) + '</div>' +
              '<div class="badge-fonction">' + echapper(p.profession || 'Membre du FDS') + '</div></div>' +
            '</div>' +
            '<div class="badge-pied">' +
              '<dl class="badge-champs">' +
                '<div><dt>N° de membre</dt><dd>' + echapper(p.numero) + '</dd></div>' +
                '<div><dt>Bureau</dt><dd>' + echapper(bureauDe(p)) + '</dd></div>' +
                '<div><dt>Ville</dt><dd>' + echapper(p.ville || '—') + '</dd></div>' +
                '<div><dt>Pays</dt><dd>' + echapper(p.pays || '—') + '</dd></div>' +
              '</dl>' +
              '<img class="badge-qr" alt="QR code du badge" src="' + qrSrc(p) + '" />' +
            '</div>' +
          '</div>' +
          '<div class="badge-bas"><span>Respect</span><span>Intégrité</span><span>Loyauté</span></div>'
        );
      }
      function rendreBadge(p) {
        var el = document.getElementById('badgeCarte');
        if (el) el.innerHTML = htmlBadge(p);
      }
      function rendreInfos(p) {
        var champs = [
          ['Nom', p.nom], ['Prénom', p.prenom], ['Genre', p.genre],
          ['Date de naissance', p.naissance ? dateFr(p.naissance) : ''],
          ['Lieu de naissance', p.lieuNaissance], ['Profession', p.profession],
          ['Ville de résidence', p.ville], ['Région', p.region || p.province],
          ['Pays', p.pays], ['Téléphone', p.tel], ['E-mail', p.email],
          ['NIP', p.nip], ['Circonscription électorale', p.circonscription],
          ['Lieu de vote', p.lieuVote], ['Bureau', bureauDe(p)], ['N° de membre', p.numero],
          ['Cotisation', libelleCotisation(p)]
        ];
        document.getElementById('mesInfos').innerHTML = champs.map(function (c) {
          return '<div><dt>' + echapper(c[0]) + '</dt><dd>' + echapper(c[1] || '—') + '</dd></div>';
        }).join('');
      }
      function fluxHTML(liste, etiquette) {
        if (!liste.length) return '<p class="flux-vide">Rien à afficher pour le moment.</p>';
        return liste.map(function (item) {
          return '<article class="flux-item"><span class="etiquette">' + etiquette + '</span>' +
            '<h4>' + echapper(item.titre) + '</h4><p>' + echapper(item.texte) + '</p></article>';
        }).join('');
      }
      function extrait(texte, n) {
        var t = String(texte || '').replace(/\s+/g, ' ').trim();
        if (t.length <= n) return t;
        return t.slice(0, n).replace(/\s+\S*$/, '') + '\u2026';
      }
      function htmlCartesMagasin(liste, type) {
        var vide = type === 'actus' ? 'Aucune actualité pour le moment.' : 'Aucune offre pour le moment.';
        if (!liste.length) return '<p class="flux-vide">' + vide + '</p>';
        var route = type === 'actus' ? 'espace-actus' : 'espace-offres';
        var etiquette = type === 'actus' ? 'Actualité' : 'Offre';
        return liste.map(function (item, i) {
          var lettre = echapper((item.titre || '?').charAt(0).toUpperCase());
          return '<a class="carte-app" href="#' + route + '/' + i + '">' +
            '<span class="carte-app-icone" aria-hidden="true">' + lettre + '</span>' +
            '<span class="carte-app-corps">' +
              '<span class="carte-app-etiquette">' + etiquette + '</span>' +
              '<strong>' + echapper(item.titre) + '</strong>' +
              '<span>' + echapper(extrait(item.texte, 110)) + '</span>' +
            '</span></a>';
        }).join('');
      }
      function rendreFiche(type, index) {
        var liste = type === 'actus' ? actualites : offres;
        var item = liste[index];
        var el = document.getElementById('ficheMagasin');
        var titreBarre = document.getElementById('titreTableau');
        if (!el) return;
        if (!item) {
          el.innerHTML = '<p class="flux-vide">Cet élément n\u2019est plus disponible.</p>';
          return;
        }
        var etiquette = type === 'actus' ? 'Actualité' : 'Offre membre';
        var lettre = echapper((item.titre || '?').charAt(0).toUpperCase());
        el.innerHTML =
          '<div class="fiche-entete">' +
            '<span class="carte-app-icone" aria-hidden="true">' + lettre + '</span>' +
            '<div><span class="carte-app-etiquette">' + etiquette + '</span>' +
            '<h3>' + echapper(item.titre) + '</h3></div>' +
          '</div>' +
          '<p>' + echapper(item.texte) + '</p>';
        if (titreBarre) titreBarre.textContent = item.titre;
      }
      function rendreFlux() {
        var htmlActus = htmlCartesMagasin(actualites, 'actus');
        var htmlOffres = htmlCartesMagasin(offres, 'offres');
        var magasinActus = document.getElementById('magasinActus');
        var magasinOffres = document.getElementById('magasinOffres');
        if (magasinActus) magasinActus.innerHTML = htmlActus;
        if (magasinOffres) magasinOffres.innerHTML = htmlOffres;
        document.getElementById('fluxActus').innerHTML = htmlActus;
        document.getElementById('fluxOffres').innerHTML = htmlOffres;
      }

      // ---------- Rendu du tableau de bord admin ----------
      var COTISATION_FCFA = 500;
      function montantFr(n) {
        return String(Math.round(n)).replace(/\B(?=(\d{3})+(?!\d))/g, '\u202f') + ' FCFA';
      }
      function libelleCotisation(p) {
        if (p && p.actif && p.cotisation) {
          return 'Compte actif \u2014 ' + montantFr(COTISATION_FCFA) + (p.cotisation.date ? ' \u00b7 ' + dateFr(p.cotisation.date) : '');
        }
        return montantFr(COTISATION_FCFA) + ' \u2014 en attente d\u2019activation';
      }
      function rendreCotisation(p) {
        var el = document.getElementById('carteMembre');
        if (!el) return;
        var actif = !!(p && p.actif && p.cotisation);
        el.className = 'carte-membre ' + (actif ? 'actif' : 'attente');
        el.innerHTML =
          '<span class="carte-membre-bloc">' +
            '<strong>Mes informations</strong>' +
            '<span class="intro">Les donn\u00e9es de ton adh\u00e9sion</span>' +
          '</span>' +
          '<span class="carte-membre-bloc">' +
            '<strong>Cotisation</strong>' +
            '<span class="etat">' + (actif ? 'Compte actif' : 'Compte en attente') + '</span>' +
            '<span class="detail">' + (actif ? 'R\u00e9gl\u00e9e \u00b7 ' : '') + montantFr(COTISATION_FCFA) + '</span>' +
          '</span>';
      }
      function htmlEtatCotisation(m) {
        if (m.actif && m.cotisation) {
          return '<span class="etat-pastille ok">Active \u00b7 ' + montantFr(COTISATION_FCFA) + '</span>';
        }
        return '<span class="etat-pastille attente">En attente \u00b7 ' + montantFr(COTISATION_FCFA) + '</span>';
      }
      function htmlSaisieCotisation(m) {
        if (m.actif && m.cotisation) return htmlEtatCotisation(m);
        var index = membresInscrits.indexOf(m);
        return htmlEtatCotisation(m) +
          '<div class="cotisation-ligne">' +
            '<button class="btn-cotis" type="button" data-cotis="' + index + '">Activer</button>' +
          '</div>';
      }
      function activerCotisation(index) {
        var m = membresInscrits[index];
        if (!m) return false;
        m.cotisation = { montant: COTISATION_FCFA, date: new Date().toISOString().slice(0, 10) };
        m.actif = true;
        return true;
      }
      function tableMembresHTML(liste, avecSaisie) {
        if (!liste.length) {
          return '<p class="flux-vide">Aucun membre inscrit pour le moment. Les inscriptions faites depuis le formulaire « Créer un compte » apparaîtront ici.</p>';
        }
        var lignes = liste.map(function (m) {
          return '<tr><td><strong>' + echapper(m.prenom) + ' ' + echapper(m.nom) + '</strong>' +
            '<small>' + echapper(m.numero) + ' — ' + echapper(bureauDe(m)) + '</small>' +
            (avecSaisie ? '' : htmlEtatCotisation(m)) + '</td>' +
            '<td>' + echapper(m.ville || '—') + '<small>' + echapper(m.region || m.province || '') + '</small></td>' +
            '<td>' + echapper(m.tel || '—') + '<small>' + echapper(m.email || '') + '</small></td>' +
            '<td>' + echapper(m.profession || '—') + '</td>' +
            (avecSaisie ? '<td>' + htmlSaisieCotisation(m) + '</td>' : '') +
            '</tr>';
        }).join('');
        return '<table class="membres"><thead><tr><th>Membre</th><th>Ville</th><th>Contact</th><th>Profession</th>' +
          (avecSaisie ? '<th>Cotisation</th>' : '') + '</tr></thead><tbody>' + lignes + '</tbody></table>';
      }
      function listeAdminHTML(liste, type) {
        if (!liste.length) return '<p class="flux-vide">Aucun élément en ligne pour le moment.</p>';
        return liste.map(function (item, i) {
          return '<article class="flux-item"><div class="txt"><h4>' + echapper(item.titre) + '</h4><p>' + echapper(item.texte) + '</p></div>' +
            '<button class="btn-suppr" type="button" data-suppr="' + type + '" data-index="' + i + '">Retirer</button></article>';
        }).join('');
      }
      function majAdmin() {
        var invite = document.getElementById('adminInvite');
        var contenu = document.getElementById('adminContenu');
        if (invite && contenu) {
          invite.hidden = !!sessionAdmin;
          contenu.hidden = !sessionAdmin;
        }
        if (!sessionAdmin) return;
        document.getElementById('statMembres').textContent = membresInscrits.length;
        document.getElementById('statActus').textContent = actualites.length;
        document.getElementById('statOffres').textContent = offres.length;
        document.getElementById('tableRecents').innerHTML = tableMembresHTML(membresInscrits.slice(-3).reverse(), false);
        document.getElementById('tableMembres').innerHTML = tableMembresHTML(membresInscrits.slice().reverse(), true);
        document.getElementById('listeActusAdmin').innerHTML = listeAdminHTML(actualites, 'actu');
        document.getElementById('listeOffresAdmin').innerHTML = listeAdminHTML(offres, 'offre');
        rendreOrgaAdmin();
        majSectionAdmin(routeDepuisHash());
      }
      function majSectionAdmin(route) {
        var section = route.indexOf('admin-') === 0 ? route.slice(6) : 'vue';
        document.querySelectorAll('.admin-menu a').forEach(function (a) {
          var on = a.getAttribute('data-admin') === section;
          a.classList.toggle('actif', on);
          if (on) a.setAttribute('aria-current', 'page');
          else a.removeAttribute('aria-current');
        });
        document.querySelectorAll('.panneau-admin').forEach(function (p) {
          p.classList.toggle('actif', p.id === 'admin-' + section);
        });
        var retour = document.getElementById('retourAdmin');
        if (retour) retour.hidden = section === 'vue';
      }
      document.getElementById('formActu').addEventListener('submit', function (e) {
        e.preventDefault();
        var titre = valeur('actuTitre');
        var texte = valeur('actuTexte');
        if (!titre || !texte) return;
        actualites.unshift({ titre: titre, texte: texte });
        e.target.reset();
        document.getElementById('okActu').hidden = false;
        majAdmin();
      });
      document.getElementById('formOffre').addEventListener('submit', function (e) {
        e.preventDefault();
        var titre = valeur('offreTitre');
        var texte = valeur('offreTexte');
        if (!titre || !texte) return;
        offres.unshift({ titre: titre, texte: texte });
        e.target.reset();
        document.getElementById('okOffre').hidden = false;
        majAdmin();
      });
      document.getElementById('page-admin').addEventListener('click', function (e) {
        var btnCotis = e.target.closest ? e.target.closest('[data-cotis]') : null;
        if (btnCotis) {
          if (activerCotisation(parseInt(btnCotis.getAttribute('data-cotis'), 10))) majAdmin();
          return;
        }
        var btnOrga = e.target.closest ? e.target.closest('[data-suppr-orga]') : null;
        if (btnOrga) {
          var listeOrga = organigrammes[btnOrga.getAttribute('data-suppr-orga')];
          if (listeOrga) listeOrga.splice(parseInt(btnOrga.getAttribute('data-index'), 10), 1);
          majAdmin();
          return;
        }
        var btn = e.target.closest ? e.target.closest('[data-suppr]') : null;
        if (!btn) return;
        var liste = btn.getAttribute('data-suppr') === 'actu' ? actualites : offres;
        liste.splice(parseInt(btn.getAttribute('data-index'), 10), 1);
        majAdmin();
      });

      // ---------- Bureaux : données, pages détail et organigrammes ----------
      var bureauEnAttente = null;
      var bureauCourant = 'gabon';
      var drapeauxSVG = {
        gabon: '<svg viewBox="0 0 36 24" aria-hidden="true"><rect width="36" height="8" fill="#009E60"/><rect y="8" width="36" height="8" fill="#FCD116"/><rect y="16" width="36" height="8" fill="#3A75C4"/></svg>',
        france: '<svg viewBox="0 0 36 24" aria-hidden="true"><rect width="12" height="24" fill="#0055A4"/><rect x="12" width="12" height="24" fill="#ffffff"/><rect x="24" width="12" height="24" fill="#EF4135"/></svg>',
        senegal: '<svg viewBox="0 0 36 24" aria-hidden="true"><rect width="12" height="24" fill="#00853F"/><rect x="12" width="12" height="24" fill="#FDEF42"/><rect x="24" width="12" height="24" fill="#E31B23"/><path d="M18 8.1l1.18 2.39 2.64.38-1.91 1.86.45 2.63L18 14.12l-2.36 1.24.45-2.63-1.91-1.86 2.64-.38z" fill="#00853F"/></svg>',
        monde: '<svg viewBox="0 0 36 24" aria-hidden="true"><rect width="36" height="24" fill="#0a2a63"/><g fill="none" stroke="#ffc61a" stroke-width="1.5"><circle cx="18" cy="12" r="7.5"/><path d="M10.5 12h15M18 4.5c2 2.1 3 4.7 3 7.5s-1 5.4-3 7.5c-2-2.1-3-4.7-3-7.5s1-5.4 3-7.5z"/></g></svg>'
      };
      var bureauxData = {
        gabon: {
          nom: 'Bureau national — Gabon', zone: 'Gabon — Siège national', drapeau: 'gabon',
          image: 'data:image/jpeg;base64,', alt: 'Le siège national du FDS à Libreville',
          intro: 'Le bureau du Gabon est le siège national du Front Démocratique Socialiste, à Libreville. Il coordonne les activités du parti sur tout le territoire gabonais et constitue le lien entre les bureaux provinciaux, les six pôles d\u2019action et la direction nationale.'
        },
        france: {
          nom: 'FDS France', zone: 'Diaspora — France', drapeau: 'france',
          image: 'data:image/jpeg;base64,', alt: 'Un membre du FDS France en chemise blanche sur fond bleu nuit',
          intro: 'Le bureau du FDS en France rassemble les Gabonaises et les Gabonais vivant en France. Il coordonne les activités du parti sur le territoire français, anime la diaspora et constitue le lien permanent entre les membres en France et le siège national de Libreville.'
        },
        senegal: {
          nom: 'FDS Sénégal', zone: 'Diaspora — Sénégal', drapeau: 'senegal',
          image: 'data:image/jpeg;base64,', alt: 'Les activités du FDS Sénégal sur le terrain',
          intro: 'Le bureau du FDS au Sénégal anime la communauté gabonaise au Sénégal — étudiants, travailleurs et familles. Il coordonne les activités du parti en Afrique de l\u2019Ouest et constitue le lien entre les membres sur place et le siège national de Libreville.'
        },
        diaspora: {
          nom: 'FDS Diaspora', zone: 'Diaspora — Monde', drapeau: 'monde',
          image: 'data:image/jpeg;base64,', alt: 'La diaspora gabonaise rassemblée à travers le monde',
          intro: 'Le réseau FDS Diaspora rattache au parti les Gabonaises et les Gabonais partout ailleurs dans le monde. Il coordonne les membres répartis dans de nombreux pays et constitue leur lien avec le Gabon, en attendant l\u2019ouverture d\u2019un bureau dans leur pays de résidence.'
        }
      };
      var organigrammes = {
        gabon: [
          { poste: 'Président national', nom: '' },
          { poste: 'Secrétaire général', nom: '' },
          { poste: 'Trésorier national', nom: '' },
          { poste: 'Responsable Communication', nom: '' },
          { poste: 'Responsable Jeunesse et Mobilisation', nom: '' }
        ],
        france: [
          { poste: 'Responsable du bureau', nom: '' },
          { poste: 'Secrétaire du bureau', nom: '' },
          { poste: 'Trésorier du bureau', nom: '' },
          { poste: 'Responsable Communication', nom: '' },
          { poste: 'Responsable Jeunesse', nom: '' }
        ],
        senegal: [
          { poste: 'Responsable du bureau', nom: '' },
          { poste: 'Secrétaire du bureau', nom: '' },
          { poste: 'Trésorier du bureau', nom: '' },
          { poste: 'Responsable Communication', nom: '' },
          { poste: 'Responsable Jeunesse', nom: '' }
        ],
        diaspora: [
          { poste: 'Coordonnateur du réseau', nom: '' },
          { poste: 'Secrétaire du réseau', nom: '' },
          { poste: 'Responsable Communication', nom: '' },
          { poste: 'Responsable Retour au pays', nom: '' }
        ]
      };
      function initialesNom(nom) {
        var morceaux = (nom || '').trim().split(/\s+/).filter(function (x) { return x; });
        if (!morceaux.length) return 'FDS';
        return (morceaux[0].charAt(0) + (morceaux.length > 1 ? morceaux[morceaux.length - 1].charAt(0) : '')).toUpperCase();
      }
      function orgaItemHTML(item, boutonSuppr) {
        return '<div class="orga-item"><div class="avatar" aria-hidden="true">' + echapper(initialesNom(item.nom)) + '</div>' +
          '<div class="txt"><div class="poste">' + echapper(item.poste) + '</div>' +
          '<div class="nom-resp">' + echapper(item.nom || 'Poste à pourvoir') + '</div></div>' + (boutonSuppr || '') + '</div>';
      }
      function rendreBureau(id) {
        var d = bureauxData[id];
        if (!d) { id = 'gabon'; d = bureauxData.gabon; }
        bureauCourant = id;
        document.title = d.nom + ' — FDS';
        var img = document.getElementById('bureauBanniere');
        img.src = d.image;
        img.alt = d.alt;
        document.getElementById('bureauZone').textContent = d.zone;
        document.getElementById('bureauDrapeau').innerHTML = drapeauxSVG[d.drapeau];
        document.getElementById('bureauNom').textContent = d.nom;
        document.getElementById('bureauIntro').textContent = d.intro;
        var liste = organigrammes[id] || [];
        document.getElementById('bureauOrga').innerHTML = liste.length
          ? liste.map(function (item) { return orgaItemHTML(item, ''); }).join('')
          : '<p class="flux-vide">L\u2019organigramme de ce bureau sera publié très prochainement.</p>';
        var actus = actualites.filter(function (a) { return !a.bureau || a.bureau === 'tous' || a.bureau === id; });
        document.getElementById('bureauActus').innerHTML = fluxHTML(actus, 'Actualité');
      }
      function rendreOrgaAdmin() {
        var conteneur = document.getElementById('orgaAdminListes');
        if (!conteneur) return;
        conteneur.innerHTML = Object.keys(bureauxData).map(function (id) {
          var d = bureauxData[id];
          var liste = organigrammes[id] || [];
          var items = liste.length
            ? liste.map(function (item, i) {
                return orgaItemHTML(item, '<button class="btn-suppr" type="button" data-suppr-orga="' + id + '" data-index="' + i + '">Retirer</button>');
              }).join('')
            : '<p class="flux-vide">Aucun responsable pour le moment : ajoute le premier poste avec le formulaire ci-dessus.</p>';
          return '<div class="orga-groupe"><h4><span class="drapeau">' + drapeauxSVG[d.drapeau] + '</span>' + echapper(d.nom) + '</h4><div class="orga">' + items + '</div></div>';
        }).join('');
      }
      document.getElementById('formOrga').addEventListener('submit', function (e) {
        e.preventDefault();
        var bureau = valeur('orgaBureau');
        var poste = valeur('orgaPoste');
        if (!poste || !organigrammes[bureau]) return;
        organigrammes[bureau].push({ poste: poste, nom: valeur('orgaNom') });
        e.target.reset();
        document.getElementById('okOrga').hidden = false;
        majAdmin();
      });

      // Liens d'attente (réseaux sociaux, courriel des bureaux) : aucune adresse inventée, clic sans effet pour le moment
      document.querySelectorAll('[data-inactif]').forEach(function (el) {
        el.addEventListener('click', function (e) { e.preventDefault(); });
      });

      document.getElementById('formAdmin').addEventListener('submit', function (e) {
        e.preventDefault();
        var id = valeur('adminIdentifiant').toLowerCase();
        var mdp = document.getElementById('adminMdp').value;
        var ok = (id === 'admin@fds.ga' && mdp === 'FdsAdmin2026');
        document.getElementById('erreurAdmin').hidden = ok;
        if (!ok) return;
        sessionAdmin = true;
        try { sessionStorage.setItem('fdsSessionAdmin', 'ok'); } catch (errSet) {}
        e.target.reset();
        majAdmin();
        majBarreTableau('admin');
      });
      document.getElementById('btnQuitterTableau').addEventListener('click', function () {
        var route = routeDepuisHash();
        if (pageId(route) === 'admin') {
          sessionAdmin = false;
          try { sessionStorage.removeItem('fdsSessionAdmin'); } catch (errQuit) {}
          majAdmin();
          majBarreTableau('admin');
          return;
        }
        sessionMembre = null;
        if (location.hash === '#accueil' || location.hash === '') afficherPage('accueil');
        else location.hash = '#accueil';
      });
      // Affichage initial selon l'adresse
      afficherPage(routeDepuisHash());
